// Bundles Observable Plot + the shared spec builder into a string the chart WebView injects.
// Run: node apps/mobile/scripts/build-plot-bundle.mjs (from repo root)
import { build } from "esbuild";
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
const here = dirname(fileURLToPath(import.meta.url));
const out = await build({
  entryPoints: [join(here, "plot-entry.ts")],
  bundle: true, minify: true, format: "iife", write: false, platform: "browser", target: "es2019",
  conditions: ["development"],
});
const code = out.outputFiles[0].text;
writeFileSync(join(here, "../lib/plot-bundle.generated.ts"),
  `// Generated by scripts/build-plot-bundle.mjs. Do not edit.\nexport const PLOT_BUNDLE = ${JSON.stringify(code)};\n`);
console.log("bytes", code.length);
